import{_ as l,l as o,o as e,c as n,v as t,p as s,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"良率学习曲线","description":"","frontmatter":{"title":"良率学习曲线","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/yield-learning-curve.md","filePath":"litho/yield-learning-curve.md","lastUpdated":1789023840000}'),c={name:"litho/yield-learning-curve.md"};function E(_,a,B,P,A,m){const i=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="良率学习曲线" tabindex="-1">良率学习曲线 <a class="header-anchor" href="#良率学习曲线" aria-label="Permalink to &quot;良率学习曲线&quot;">​</a></h1><div class="epigraph"><p>新节点的良率不是一条平滑指数；它是系统热点被一项项杀掉、随机密度被一轮轮压低的阶梯，学习速度由检测–分类–改版闭环决定。</p><footer>—— 对照半导体 yield learning 与缺陷学习周期的公开讨论</footer></div><p><a href="/litho/defect-review-classification">上一课</a>给出可行动 Pareto。缺口是时间：从首片到目标良率，闭环转多快。<a href="/litho/dtco-patterning">DTCO</a> 已说规则冻结前应少留系统债；本课钉量产后的学习。参数良率与 CD 分布，留给[下一课](/litho/parametric-yield-cd）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>学习曲线：良率对周或对累计晶圆。系统项呈阶跃（一次 OPC 改版、一次规则、一次食谱），随机项呈缓坡（洁净、过滤、剂量优化）。若检测看不见 stoch，曲线会在光学 Pareto 耗尽后平台——假成熟。改版周期（掩模、OPC）是学习的节拍，比 APC 慢得多。</p><p>缺口是<strong>把学习当项目管理</strong>，不是拟合一条 \\(Y=1-e^{-t/\\tau}\\) 就结束。每阶跃要对应 Pareto 头号杀手的关闭条件。</p><h3 id="学习与产能抢掩模" tabindex="-1">学习与产能抢掩模 <a class="header-anchor" href="#学习与产能抢掩模" aria-label="Permalink to &quot;学习与产能抢掩模&quot;">​</a></h3><p>加密 PWQ、改 OPC、新切线版都吃掩模与扫描机时间。学习太猛伤交付；太慢把系统缺陷固化进库存。分派与工程片额度是这条曲线的显式资源。</p><p><span class="marginnote">把 APC 把均值钉住当成「学会了」。能力（窗口、随机 p）没动，曲线只是方差变小，天花板还在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>跟踪：按类的缺陷密度与系统 clips 关闭率。节奏：热点库版本、OPC 版本、食谱版本与良率阶跃对齐。与设计：LFD 回馈是否进入下一产品。与 IRDS 类路线图（后课程）的密度目标对比：本课只要求曲线可解释。</p><p>周会只看总良率会把阶跃和缓坡搅在一起。看板应按类：头号系统 clips 是否关闭、光学颗粒 \\(D\\)、电子束 \\(p\\)。关闭条件预先写好，避免「再观察一周」变成平台。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>系统关闭：一次改版令 \\(Y_\\mathrm{sys}\\) 跳变。随机：\\(D(t)\\) 随洁净与工艺缓降，\\(Y_\\mathrm{rand}=e^{-D(t)A}\\)。总良率乘积。平台 = 看不见的类或改版停摆。边缘场若从未进学习样本，出货量上升（用满边缘）时曲线会倒退。</p>',14)),(e(),s(h,null,{default:r(()=>[p(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAR%5B%22%E5%A4%8D%E6%A3%80%20Pareto%22%5D%20--%3E%20ACT%5B%22%E6%94%B9%20OPC%20%2F%20%E9%A3%9F%E8%B0%B1%20%2F%20%E6%B4%81%E5%87%80%22%5D%0A%20%20ACT%20--%3E%20STEP%5B%22%E7%B3%BB%E7%BB%9F%E9%98%B6%E8%B7%83%22%5D%0A%20%20ACT%20--%3E%20SLOPE%5B%22%E9%9A%8F%E6%9C%BA%E7%BC%93%E5%9D%A1%22%5D%0A%20%20STEP%20--%3E%20Y%5B%22%E8%89%AF%E7%8E%87%22%5D%0A%20%20SLOPE%20--%3E%20Y%0A%20%20BLIND%5B%22%E6%A3%80%E6%B5%8B%E7%9B%B2%E5%8C%BA%22%5D%20--%3E%20PLAT%5B%22%E5%81%87%E5%B9%B3%E5%8F%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>系统关闭呈阶跃，随机呈缓坡。检测盲区会在放量后让曲线倒退，看板必须按类而不是只看总良率。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不编造某节点学习周数。不把财务良率（含封装）与晶圆探针混报。本课不写限价。</p><p>后课默认：学习曲线按类解释，系统阶跃对随机缓坡。下一课即使缺陷为零，CD 分布仍会杀掉参数良率。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>学习是系统阶跃乘随机缓坡，节拍是改版与检测可见性。</li><li>APC 钉均值 ≠ 学会能力。</li><li>边缘与 stoch 盲区会在放量时让曲线倒退。</li><li>出处：半导体 yield learning 通称；缺陷学习周期公开讨论。</li></ul>',6))])}const C=l(c,[["render",E]]);export{f as __pageData,C as default};
